public class ValueChainTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        ValueChain<String> tail = ValueChain.of("b");
        checkCall("of(b).length()", 1, () -> tail.length());
        checkCall("of(b).toList()", "[b]", () -> String.valueOf(tail.toList()));

        checkCall("prepend chain toList()", "[a, b]", () -> tail.prepend("a").toList().toString());
        checkCall("original chain is unchanged", "[b]", () -> {
            tail.prepend("a");
            return tail.toList().toString();
        });
        checkCall("three-link length()", 3, () -> ValueChain.of(3).prepend(2).prepend(1).length());
        checkCall("valueAt(1)", 2, () -> ValueChain.of(3).prepend(2).prepend(1).valueAt(1));
        checkCall("valueAt past the end", null, () -> ValueChain.of(3).prepend(2).valueAt(9));
        checkCall("valueAt(-1)", null, () -> tail.valueAt(-1));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

