import java.util.ArrayList;
import java.util.List;

public class ValueChain<T> {

    private final T head;
    private final ValueChain<T> rest;

    private ValueChain(T head, ValueChain<T> rest) {
        this.head = head;
        this.rest = rest;
    }

    public static <T> ValueChain<T> of(T value) {
        return new ValueChain<>(value, null);
    }

    public ValueChain<T> prepend(T value) {
        return new ValueChain<>(value, this);
    }

    public int length() {
        int count = 0;
        ValueChain<T> cell = this;
        while (cell != null) {
            count++;
            cell = cell.rest;
        }
        return count;
    }

    public T valueAt(int index) {
        if (index < 0) {
            return null;
        }
        ValueChain<T> cell = this;
        int position = 0;
        while (cell != null) {
            if (position == index) {
                return cell.head;
            }
            position++;
            cell = cell.rest;
        }
        return null;
    }

    public List<T> toList() {
        List<T> out = new ArrayList<>();
        ValueChain<T> cell = this;
        while (cell != null) {
            out.add(cell.head);
            cell = cell.rest;
        }
        return out;
    }
}
